examples.code:
terraform {
  required_version = "~> 1.14"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.7"
    }
  }
}

provider "aws" {
  region = var.region
  assume_role {
    role_arn = "arn:aws:iam::123456789012:role/terraform"
  }
  default_tags {
    tags = {
      Proyecto  = "tienda"
      Entorno   = var.entorno
      ManagedBy = "terraform"
    }
  }
}

provider "aws" {
  alias  = "virginia"
  region = "us-east-1"
}
resource "aws_acm_certificate" "cdn" {
  provider          = aws.virginia
  domain_name       = "ejemplo.cl"
  validation_method = "DNS"
}

variable "entorno" {
  type        = string
  description = "Entorno de despliegue"
  validation {
    condition     = contains(["dev", "staging", "prod"], var.entorno)
    error_message = "entorno debe ser dev, staging o prod."
  }
}
variable "bucket_name" {
  type = string
  validation {
    condition     = can(regex("^[a-z0-9.-]{3,63}$", var.bucket_name))
    error_message = "Nombre de bucket S3 inválido."
  }
}

variable "servicios" {
  type = map(object({
    puerto   = number
    replicas = optional(number, 2)
    publico  = optional(bool, false)
  }))
}

variable "db_password" {
  type      = string
  sensitive = true
  nullable  = false
}

entorno       = "prod"
instance_type = "m7i.large"
servicios = {
  api = { puerto = 8000, replicas = 4, publico = true }
  worker = { puerto = 9000 }
}

locals {
  prefijo = "${var.proyecto}-${var.entorno}"
  tags_comunes = merge(var.tags, {
    Proyecto = var.proyecto
    Entorno  = var.entorno
  })
}
resource "aws_s3_bucket" "assets" {
  bucket = "${local.prefijo}-assets"
  tags   = local.tags_comunes
}

output "vpc_id" {
  value       = aws_vpc.main.id
  description = "ID de la VPC"
}
output "db_endpoint" {
  value = aws_db_instance.main.endpoint
}
output "db_password" {
  value     = random_password.db.result
  sensitive = true
}

variable "subredes" {
  default = {
    "us-east-1a" = "10.20.1.0/24"
    "us-east-1b" = "10.20.2.0/24"
  }
}
resource "aws_subnet" "private" {
  for_each          = var.subredes
  vpc_id            = aws_vpc.main.id
  availability_zone = each.key
  cidr_block        = each.value
  tags              = { Name = "private-${each.key}" }
}

output "subnet_ids" {
  value = [for s in aws_subnet.private : s.id]
}

resource "aws_iam_user" "equipo" {
  for_each = toset(["nicolas", "camila", "diego"])
  name     = each.value
}

resource "aws_instance" "bastion" {
  count         = var.crear_bastion ? 1 : 0
  ami           = data.aws_ami.ubuntu.id
  instance_type = "t3.micro"
}
output "bastion_ip" {
  value = one(aws_instance.bastion[*].public_ip)
}

resource "aws_instance" "web" {
  count         = 3
  ami           = data.aws_ami.ubuntu.id
  instance_type = "t3.small"
  tags          = { Name = "web-${count.index}" }
}

variable "puertos_abiertos" {
  default = [80, 443]
}
resource "aws_security_group" "web" {
  name   = "web"
  vpc_id = aws_vpc.main.id
  dynamic "ingress" {
    for_each = var.puertos_abiertos
    content {
      from_port   = ingress.value
      to_port     = ingress.value
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    }
  }
}

data "aws_ami" "ubuntu" {
  most_recent = true
  owners      = ["099720109477"]
  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd-gp3/ubuntu-noble-24.04-amd64-server-*"]
  }
}

data "aws_availability_zones" "disponibles" {
  state = "available"
}
data "aws_caller_identity" "actual" {}
locals {
  azs        = slice(data.aws_availability_zones.disponibles.names, 0, 3)
  account_id = data.aws_caller_identity.actual.account_id
}

locals {
  nombres_mayus = [for n in var.nombres : upper(n)]
  ids_por_nombre = { for i in aws_instance.web : i.tags.Name => i.id }
  solo_publicos = { for k, v in var.servicios : k => v if v.publico }
  ips = aws_instance.web[*].private_ip
  tamano = var.entorno == "prod" ? "m7i.large" : "t3.small"
}

resource "aws_instance" "app" {
  user_data = templatefile("${path.module}/cloud-init.yaml.tftpl", {
    hostname = "app-01"
    paquetes = ["nginx", "git"]
  })
}

resource "aws_db_instance" "main" {
  # ...
  lifecycle {
    prevent_destroy = true
    ignore_changes  = [engine_version]
  }
}

resource "aws_launch_template" "app" {
  # ...
  lifecycle { create_before_destroy = true }
}
resource "aws_instance" "app" {
  # ...
  lifecycle {
    replace_triggered_by = [aws_launch_template.app.latest_version]
  }
}

resource "aws_instance" "web" {
  ami           = data.aws_ami.ubuntu.id
  instance_type = var.instance_type
  lifecycle {
    precondition {
      condition     = data.aws_ami.ubuntu.architecture == "x86_64"
      error_message = "La AMI debe ser x86_64 para este tipo de instancia."
    }
    postcondition {
      condition     = self.public_ip != ""
      error_message = "La instancia no recibió IP pública."
    }
  }
}

check "api_salud" {
  data "http" "health" {
    url = "https://api.ejemplo.cl/health"
  }
  assert {
    condition     = data.http.health.status_code == 200
    error_message = "La API devolvió ${data.http.health.status_code}."
  }
}

resource "aws_lambda_function" "fn" {
  # ...
  depends_on = [aws_iam_role_policy_attachment.logs]
}

ephemeral "aws_secretsmanager_secret_version" "db" {
  secret_id = "prod/tienda/db"
}
provider "postgresql" {
  host     = aws_db_instance.main.address
  username = "admin"
  password = jsondecode(ephemeral.aws_secretsmanager_secret_version.db.secret_string)["password"]
}

ephemeral "random_password" "db" {
  length  = 32
  special = true
}

variable "token_api" {
  type      = string
  ephemeral = true
}

resource "aws_security_group" "web" {
  name   = "web-sg"
  vpc_id = module.vpc.vpc_id
  ingress {
    description = "SSH desde la oficina"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.ip_oficina]
  }
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
resource "aws_instance" "web" {
  ami                    = data.aws_ami.ubuntu.id
  instance_type          = "t3.small"
  subnet_id              = module.vpc.public_subnets[0]
  vpc_security_group_ids = [aws_security_group.web.id]
  metadata_options { http_tokens = "required" }
  root_block_device {
    volume_size = 20
    encrypted   = true
  }
  tags = { Name = "web-01" }
}

resource "aws_s3_bucket" "logs" {
  bucket = "nicocano-logs-prod"
}
resource "aws_s3_bucket_public_access_block" "logs" {
  bucket                  = aws_s3_bucket.logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}
resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id
  rule {
    apply_server_side_encryption_by_default { sse_algorithm = "aws:kms" }
  }
}
resource "aws_s3_bucket_lifecycle_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id
  rule {
    id     = "expirar"
    status = "Enabled"
    filter {}
    expiration { days = 90 }
  }
}

provider "google" {
  project = "nicocano-prod"
  region  = "southamerica-west1"
}
resource "google_storage_bucket" "assets" {
  name                        = "nicocano-assets-prod"
  location                    = "SOUTHAMERICA-WEST1"
  uniform_bucket_level_access = true
  public_access_prevention    = "enforced"
  versioning { enabled = true }
}

provider "azurerm" {
  features {}
  subscription_id = var.subscription_id
}
resource "azurerm_resource_group" "rg" {
  name     = "rg-tienda-prod"
  location = "brazilsouth"
}
resource "azurerm_storage_account" "sa" {
  name                     = "nicocanotiendaprod"
  resource_group_name      = azurerm_resource_group.rg.name
  location                 = azurerm_resource_group.rg.location
  account_tier             = "Standard"
  account_replication_type = "ZRS"
  min_tls_version          = "TLS1_2"
}

locals {
  arn = provider::aws::arn_parse("arn:aws:iam::123456789012:role/terraform")
  cuenta = local.arn.account_id
}
